import numpy as np
from logreg import LogisticRegression

def trial(standardize, div_m, lr):
    m=LogisticRegression(); X,Y=m.load_csv('dataset.csv')
    if standardize:
        mu=X.mean(0); sd=X.std(0); X=(X-mu)/sd
    th=np.zeros(X.shape[1]); n=X.shape[0]; conv=-1
    for i in range(1,100001):
        p=1/(1+np.exp(-np.clip(X.dot(th),-700,700)))
        g=X.T.dot(Y-p)/(n if div_m else 1.0)
        pt=th.copy(); th=th+lr*g; d=np.linalg.norm(th-pt)
        if d<1e-15: conv=i; break
    acc=np.mean((1/(1+np.exp(-np.clip(X.dot(th),-700,700)))>=0.5).astype(int)==Y)
    return conv, d, acc, np.abs(th).max()

for std in [False,True]:
  for dm in [False,True]:
    for lr in [0.1,1.0]:
      print('std',std,'div_m',dm,'lr',lr, trial(std,dm,lr))
EOF
